'use strict';
const modules=window.COURSE.modules, lessons=modules.flatMap(m=>m.lessons.map(l=>({...l,module:m}))),KEY='college-course-v1';
let state={done:[],notes:{},quizzes:{}},storageOK=true,toastTimer;
try{const v=JSON.parse(localStorage.getItem(KEY)||'null');if(v&&Array.isArray(v.done)&&v.notes&&v.quizzes)state=v;}catch(e){storageOK=false;}
const totalLessons=lessons.length,totalModules=modules.length,totalUnits=totalLessons+totalModules,totalQuestions=modules.reduce((n,m)=>n+m.quiz.length,0);
const main=document.getElementById('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(t){document.getElementById('status').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('status').textContent='',3000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;return true;}catch(e){storageOK=false;notify('This browser could not save your work. Download your workbook before leaving.');return false;}}
function score(m){const a=state.quizzes[m.id];return a?m.quiz.reduce((s,q,i)=>s+(a[i]===q.answer?1:0),0):null;}
function stats(){return{done:lessons.filter(l=>state.done.includes(l.id)).length,passed:modules.filter(m=>score(m)>=2).length};}
function nav(){const s=stats();let n=s.done+s.passed;document.getElementById('progress').max=totalUnits;document.getElementById('progress').value=n;document.getElementById('progress-label').textContent=Math.round(n/totalUnits*100)+'%';document.getElementById('progress-detail').textContent=s.done+'/'+totalLessons+' lessons · '+s.passed+'/'+totalModules+' quizzes passed';
const hash=location.hash.slice(1)||'home';document.getElementById('modules-nav').innerHTML=modules.map(m=>`<details class="module-nav" ${m.lessons.some(l=>hash==='lesson/'+l.id)||hash==='quiz/'+m.id?'open':''}><summary><span class="number">${String(m.id).padStart(2,'0')}</span>${esc(m.title)}</summary>${m.lessons.map(l=>`<a class="lesson-nav ${hash==='lesson/'+l.id?'active':''} ${state.done.includes(l.id)?'done':''}" ${hash==='lesson/'+l.id?'aria-current="page"':''} href="#lesson/${l.id}">${esc(l.title)}</a>`).join('')}<a class="lesson-nav ${hash==='quiz/'+m.id?'active':''} ${score(m)>=2?'done':''}" href="#quiz/${m.id}">Module knowledge check</a></details>`).join('');document.querySelectorAll('.navlink').forEach(a=>a.classList.toggle('active',a.hash===location.hash));}
function warning(){return storageOK?'':'<p class="storage-warning">Saving is unavailable in this browser. Keep this page open and download your workbook before leaving.</p>';}
function nextTask(){for(const m of modules){const l=m.lessons.find(l=>!state.done.includes(l.id));if(l)return'lesson/'+l.id;if(!(score(m)>=2))return'quiz/'+m.id;}return'workbook';}
function overview(){const s=stats();const complete=s.done===totalLessons&&s.passed===totalModules;main.innerHTML=`${warning()}<div class="page-top"><p class="eyebrow">Your application starts here</p><h1>Build your college application,<br>one step at a time.</h1><p class="intro">A practical, self-paced course for students in Rwanda. Learn the process, practise with examples, and build your own application plan.</p><div class="metrics"><span><strong>${totalModules}</strong> modules</span><span><strong>${totalLessons}</strong> lessons</span><span><strong>${totalQuestions}</strong> quiz questions</span><span><strong>10–12 hours</strong> suggested study time</span></div><div class="actions"><a class="button" href="#${nextTask()}">${s.done?'Continue learning':'Start module 1'}</a><a class="button secondary" href="#pathways">Choose my year group</a><a class="button secondary" href="#roadmap">Explore the roadmap</a></div></div>${complete?`<div class="success"><h2>Course complete</h2><p>You have completed all ${totalLessons} lessons and passed all ${totalModules} knowledge checks. Download your workbook and review your real application requirements with your counsellor.</p></div>`:''}<div class="overview-layout"><section aria-label="Course modules"><p class="eyebrow">Your learning path</p><div class="path">${modules.map(m=>{const n=m.lessons.filter(l=>state.done.includes(l.id)).length;return`<article class="module-card"><div class="index">${String(m.id).padStart(2,'0')}</div><div><h3>${esc(m.title)}</h3><p>${esc(m.goal)}</p><div class="module-meta"><span>${m.lessons.length} lessons</span><span>${n}/${m.lessons.length} complete</span><span>${score(m)>=2?'Quiz passed':'3-question check'}</span></div><p class="small"><strong>You will build:</strong> ${esc(m.output)}</p><a class="button secondary" href="#lesson/${(m.lessons.find(l=>!state.done.includes(l.id))||m.lessons[0]).id}">${n?'Continue module':'Open module'}</a></div></article>`;}).join('')}</div></section><aside class="study-note"><h2>Learn. Practise. Apply.</h2><p>Take one or two lessons at a time. Each lesson has a short reading and a practical activity you can save in your workbook.</p><ul><li>Complete the activities using your own experiences.</li><li>Answer each module’s three questions. Two correct answers pass the check; you can retry.</li><li>Download your workbook regularly, especially on a shared computer.</li></ul><p>Your application writing and research will take additional time beyond the suggested course study time.</p><h3>Use current requirements</h3><p>Examples are fictional. The course focuses on US and UK applications, with planning tools for other destinations. Verify the current instructions for every institution.</p><a href="assets/College_Application_Guide.pdf" download>Download the 50-page guide</a><p class="small" style="margin-top:18px">Course expanded 30 September 2026 with the supplied Further Education Pathway curriculum, career readiness topics and college roadmaps. The original 50-page guide remains available; the new lessons are online and their activities appear in your workbook.</p></aside></div>`;}
function lesson(id){const l=lessons.find(x=>x.id===id);if(!l){notFound();return;}const m=l.module,ix=m.lessons.findIndex(x=>x.id===id),done=state.done.includes(id);let next=ix<m.lessons.length-1?'lesson/'+m.lessons[ix+1].id:'quiz/'+m.id;main.innerHTML=`${warning()}<div class="lesson-head page-top"><div class="breadcrumb"><a href="#home">Course</a> / Module ${m.id} / Lesson ${ix+1} of ${m.lessons.length}</div><p class="eyebrow">${esc(m.verb)} · ${l.minutes} min including practice</p><h1>${esc(l.title)}</h1><p class="intro">${esc(m.goal)}</p><span class="tag">${l.guidePage?'Companion guide · page '+l.guidePage:esc(l.sourceLabel)}</span></div><div class="reader-layout"><div><article class="lesson-content">${l.html}</article><div class="lesson-bottom">${ix?`<a class="button secondary" href="#lesson/${m.lessons[ix-1].id}">Previous lesson</a>`:'<a class="button secondary" href="#home">Course overview</a>'}<a class="button" href="#${next}">${ix<m.lessons.length-1?'Next lesson':'Take the module quiz'}</a></div></div><aside class="activity"><p class="eyebrow">Put it into practice</p><h2>Your activity</h2><p>${esc(l.activity)}</p><label for="response">My response and next action</label><textarea id="response" placeholder="Write brief notes, your evidence and the next step you will take. Avoid passwords or sensitive financial details.">${esc(state.notes[id]||'')}</textarea><p id="save-hint" class="save-hint">${state.notes[id]?'Saved on this device.':'Notes save automatically on this device.'}</p><button class="primary" id="complete">${done?'Completed · mark unfinished':'Mark lesson complete'}</button><a class="navlink" href="#workbook" style="color:var(--blue);padding-left:0">View my application workbook</a><p class="save-hint">On a shared computer, download your work and clear your course data when finished. Notes do not sync across devices.</p></aside></div>`;
document.getElementById('response').addEventListener('input',e=>{state.notes[id]=e.target.value;const ok=save();document.getElementById('save-hint').textContent=ok?'Saved on this device.':'Not saved. Download your workbook before leaving.';});document.getElementById('complete').onclick=()=>{if(state.done.includes(id))state.done=state.done.filter(x=>x!==id);else state.done.push(id);save();nav();document.getElementById('complete').textContent=state.done.includes(id)?'Completed · mark unfinished':'Mark lesson complete';notify(state.done.includes(id)?'Lesson marked complete.':'Lesson marked unfinished.');};}
function quiz(id){const m=modules.find(m=>String(m.id)===id);if(!m){notFound();return;}const prev=state.quizzes[m.id];main.innerHTML=`${warning()}<div class="page-top"><div class="breadcrumb"><a href="#home">Course</a> / Module ${m.id}</div><p class="eyebrow">Knowledge check</p><h1>${esc(m.title)}</h1><p class="intro">Answer all three questions. Two correct answers pass this check. Read the explanations and retry whenever you need.</p></div><div class="quiz-wrap"><form id="quiz-form">${m.quiz.map((q,i)=>`<fieldset class="question"><legend>${i+1}. ${esc(q.q)}</legend>${q.options.map((o,j)=>`<label class="option"><input type="radio" name="q${i}" value="${j}" required ${prev&&prev[i]===j?'checked':''}><span>${esc(o)}</span></label>`).join('')}<div id="feedback-${i}"></div></fieldset>`).join('')}<button class="primary" type="submit">Check my answers</button></form><div id="quiz-result" role="status"></div></div>`;document.getElementById('quiz-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const a=m.quiz.map((q,i)=>Number(f.get('q'+i)));state.quizzes[m.id]=a;save();nav();feedback(m,a);};if(prev)feedback(m,prev);}
function feedback(m,a){let n=score(m);m.quiz.forEach((q,i)=>{const good=a[i]===q.answer;document.getElementById('feedback-'+i).innerHTML=`<p class="feedback ${good?'':'wrong'}"><strong>${good?'Correct.':'Review this answer.'}</strong> ${esc(q.why)}${good?'':`<br>Correct answer: ${esc(q.options[q.answer])}`}</p>`;});const firstUnfinished=m.lessons.find(l=>!state.done.includes(l.id));const route=firstUnfinished?'lesson/'+firstUnfinished.id:m.id<totalModules?'lesson/'+modules[m.id].lessons[0].id:'workbook';document.getElementById('quiz-result').innerHTML=`<div class="result"><h2>${n}/3 correct · ${n>=2?'Passed':'Keep practising'}</h2><p>${n>=2?'You passed this knowledge check. You can still review any question.':'Read the explanations, change your choices, and check again.'}</p><div class="actions"><a class="button secondary" href="#lesson/${m.lessons[0].id}">Review this module</a>${n>=2?`<a class="button" href="#${route}">${firstUnfinished?'Finish module lessons':m.id<totalModules?'Continue to next module':'Open my workbook'}</a>`:''}</div></div>`;}
function downloadWorkbook(){const s=stats();const lines=['MY COLLEGE APPLICATION WORKBOOK','Downloaded '+new Date().toLocaleDateString(),`${s.done}/${totalLessons} lessons complete; ${s.passed}/${totalModules} module quizzes passed.`,'Notes are student-written and have not been assessed.',''];for(const m of modules){lines.push('MODULE '+m.id+' — '+m.title,'Outcome: '+m.output);for(const l of m.lessons)if(state.notes[l.id]?.trim())lines.push('\n'+l.title,'Activity: '+l.activity,state.notes[l.id],'');lines.push('Knowledge check: '+(score(m)===null?'Not attempted':score(m)+'/3'), '\n');}const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='My_College_Application_Workbook.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Workbook download prepared.');}
function workbook(){const saved=lessons.filter(l=>state.notes[l.id]?.trim());const s=stats();main.innerHTML=`${warning()}<div class="page-top"><p class="eyebrow">Your work in one place</p><h1>My application workbook</h1><p class="intro">Your activity responses, ready to review with a counsellor or family member. These notes stay in this browser; they are not submitted to a school or university.</p><div class="metrics"><span><strong>${saved.length}</strong> saved responses</span><span><strong>${s.done}/${totalLessons}</strong> lessons complete</span><span><strong>${s.passed}/${totalModules}</strong> quizzes passed</span></div><div class="actions"><button class="primary" id="download">Download my workbook</button><button class="secondary" id="print">Print my workbook</button><button class="secondary" id="clear">Clear my course data</button></div></div>${saved.length?saved.map(l=>`<section class="work-entry"><p class="eyebrow">Module ${l.module.id} · ${esc(l.module.title)}</p><h3>${esc(l.title)}</h3><p class="small muted">${esc(l.activity)}</p><pre>${esc(state.notes[l.id])}</pre><a href="#lesson/${l.id}">Edit this response</a></section>`).join(''):'<div class="empty"><h2>Your workbook is ready for your first response.</h2><p>Open a lesson and write in its activity field. Your notes will appear here.</p><a class="button" href="#lesson/3">Begin the first lesson</a></div>'}`;document.getElementById('download').onclick=downloadWorkbook;document.getElementById('print').onclick=()=>window.print();document.getElementById('clear').onclick=()=>{if(confirm('Clear all notes, lesson progress and quiz answers on this device? Download your workbook first if you want to keep it.')){state={done:[],notes:{},quizzes:{}};save();nav();workbook();notify('Course data cleared on this device.');}};}
function resources(){main.innerHTML=`<div class="page-top"><p class="eyebrow">Keep reliable sources close</p><h1>Resources and companion guide</h1><p class="intro">Use the guide for offline reading. Check current university and platform instructions before applying.</p><div class="actions"><a class="button" href="assets/College_Application_Guide.pdf" download>Download PDF guide</a><a class="button secondary" href="assets/College_Application_Guide.docx" download>Download Word guide</a></div></div><div class="actions"><a class="button secondary" href="#career-resources">Career readiness resources · 38 topics</a><a class="button secondary" href="#roadmap">Two visual roadmaps</a><a class="button secondary" href="#pathways">EY–S6 learning paths</a></div><article class="resource-content">${window.COURSE.resources}</article>`;}
function support(){main.innerHTML=`<div class="page-top"><p class="eyebrow">Support the learner</p><h1>For teachers and families</h1><p class="intro">Help students find evidence, ask questions and plan realistic next steps. The student owns their choices and writing.</p></div><article class="resource-content"><h2>Align the course with EY–S6</h2><p>The <a href="#pathways">year-group learning paths</a> adapt the supplied CRC Further Education Pathway outline (29 August 2025). Its school learning targets are planning benchmarks, not universal admission requirements. The internal source document is not offered as a public download.</p><p>Use a simple portfolio rubric: 0 = missing, 1 = draft, 2 = clear evidence with a next step. Review authenticity, research quality, feasibility and reflection. Give one specific improvement before the next checkpoint. Do not require students to disclose private experiences in a group.</p><h2>Use the course in a group</h2><p>Assign one module at a time. Let students complete the readings, save their activities and take the knowledge check. Use the module output as the focus of a short discussion. Students can download their workbook to share when they choose.</p><p>This course does not collect a class register or send scores to teachers. Progress and notes are stored only in the learner’s browser. On shared devices, remind students to download their work and clear their course data.</p><h2>Assess application readiness</h2><p>Ask students to explain their evidence, identify a remaining question and name their next action. Quiz completion shows practice with the course concepts; it is not proof of admission eligibility or a completed application.</p>${window.COURSE.facilitator}</article>`;}
function notFound(){main.innerHTML='<h1>Lesson not found</h1><p>Choose a lesson from the course overview.</p><a class="button" href="#home">Course overview</a>';}
function render(){const [kind,id]=(location.hash.slice(1)||'home').split('/');if(kind==='lesson')lesson(id);else if(kind==='quiz')quiz(id);else if(kind==='workbook')workbook();else if(kind==='resources')resources();else if(kind==='support')support();else if(kind==='pathways')pathways();else if(kind==='roadmap')roadmap();else if(kind==='career-resources')careerResources();else overview();nav();document.getElementById('sidebar').classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);main.focus({preventScroll:true});document.title=(main.querySelector('h1')?.textContent||'Course')+' | College Application Course';}
document.getElementById('menu').onclick=()=>{const open=document.getElementById('sidebar').classList.toggle('open');document.getElementById('menu').setAttribute('aria-expanded',String(open));};window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){const controller=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'read_course_progress',title:'Read course progress',description:'Read completed lesson counts and module knowledge-check results on this device.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({...stats(),totalLessons,totalQuizzes:totalModules})},{signal:controller.signal})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'open_course_lesson',title:'Open a course lesson',description:'Navigate to an existing lesson without marking it complete or changing notes.',inputSchema:{type:'object',properties:{lessonId:{type:'string',enum:lessons.map(l=>l.id)}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.lessonId!=='string'||!lessons.some(l=>l.id===input.lessonId))throw new Error('Unknown lesson ID');history.replaceState(null,'','#lesson/'+input.lessonId);render();return{openedLessonId:input.lessonId};}},{signal:controller.signal})).catch(()=>{});window.addEventListener('pagehide',()=>controller.abort(),{once:true});}catch(e){/* Core course works without this optional browser API. */}}
